const take = (flag) => { const i = args.indexOf(flag); if (i < 0) return null; const v = args[i + 1]; args.splice(i, 2); return v; };
const FROM = take('--from'), OFF0 = +(take('--offset') || 2000);
if (FROM) { MUTANTS.length = 0; MUTANTS.push(...JSON.parse(fs.readFileSync(path.resolve(FROM), 'utf8'))); }
const filters = args.filter((a) => !a.startsWith('-'));
const want = (m) => !filters.length || filters.some((f) => m.check.includes(f) || m.id.includes(f));

function allChecks() {
  return fs.readdirSync(HERE).filter((f) => /check\.js$/.test(f) && !/^(checkall|breakall|breakcheck)\.js$/.test(f)).map((f) => f.replace(/\.js$/, '')).concat(['contracts/paritycheck']).sort();
}

if (LIST) {
  const by = new Map(); for (const m of MUTANTS) by.set(m.check, (by.get(m.check) || 0) + 1);
  for (const m of MUTANTS) console.log(`  ${m.check.padEnd(18)} ${m.id.padEnd(26)} ${m.file}\n  ${' '.repeat(18)} ${m.why}`);
  const none = allChecks().filter((c) => !by.has(c));
  console.log(`\n  ${MUTANTS.length} mutants over ${by.size} checks`);
  console.log(`  ${none.length} checks with NO mutant here${none.length ? ': ' + none.join(', ') : ''}\n`);
  process.exit(0);
}

// Each job gets its own port offset, so two mutants running at once never share a debug port with each other -
// or with anybody's `checkall.js`, whose ports are the unshifted ones.
const OFFSETS = [0, 1, 2, 3, 4, 5, 6, 7].map((k) => OFF0 + 1000 * k);

function runCheck(stg, check, env, offset, capMs = 15 * 60 * 1000) {
  return new Promise((done) => {
    // a check outside estate/'s top level is named by its path from estate/ (contracts/paritycheck)
    const file = path.join(stg.estate, check + '.js');
    const t0 = Date.now();
    const p = spawn(process.execPath, [file], { cwd: path.dirname(file), detached: true,
      env: Object.assign({}, process.env, { RF_SITE: stg.origin(), RF_PORT_OFFSET: String(offset) }, env || {}) });
    let out = '';
    p.stdout.on('data', (d) => { out += d; }); p.stderr.on('data', (d) => { out += d; });
    const timer = setTimeout(() => { out += '\n[breakall: killed after ' + capMs / 1000 + ' s]'; try { process.kill(-p.pid, 'SIGTERM'); } catch (_) {} }, capMs);
    p.on('close', (code) => { clearTimeout(timer); done({ code, out, ms: Date.now() - t0, timedOut: /\[breakall: killed/.test(out) }); });
  });
}

async function withStage(fn) {
  const stg = stage();
  try { await stg.serve(); return await fn(stg); } finally { stg.remove(); }
}

const failLines = (out) => out.split('\n').filter((l) => /\bFAIL\b/.test(l)).map((l) => l.trim().slice(0, 220));

(async () => {
  const todo = MUTANTS.filter(want);
  if (!todo.length) { console.log('no mutant matches ' + filters.join(' ')); process.exit(1); }
  const checks = [...new Set(todo.map((m) => m.check))];
  console.log(`\n  ${todo.length} mutant(s) over ${checks.length} check(s), ${JOBS} at a time${BASELINE ? ', each check run clean first' : ', NO clean runs'}\n`);

  const slots = OFFSETS.slice(0, JOBS);
  const pool = async (items, work) => { const q = items.slice(); await Promise.all(slots.map(async (off) => { while (q.length) await work(q.shift(), off); })); };

  const clean = new Map();
  if (BASELINE) await pool(checks, async (c, off) => {
    const r = await withStage((stg) => runCheck(stg, c, null, off));
    clean.set(c, r);
    console.log(`  ${r.code === 0 && !/^NOT RUN:/m.test(r.out) ? 'clean ' : 'RED   '} ${c.padEnd(18)} unmutated, ${(r.ms / 1000).toFixed(1)}s`
      + (r.code === 0 ? '' : '   ' + (failLines(r.out)[0] || r.out.trim().split('\n').slice(-1)[0] || '').slice(0, 160)));
  });

  const results = [];
  await pool(todo, async (m, off) => {
    const res = await withStage(async (stg) => {
      const f = stg.materialize(m.file);
      const src = fs.readFileSync(f, 'utf8'), n = src.split(m.find).length - 1;
      if (n !== 1) return { verdict: 'STALE', note: `"${m.find.slice(0, 60)}" is in ${m.file} ${n} times, not once - the mutant edits nothing it can name` };
      fs.writeFileSync(f, src.replace(m.find, () => m.replace));
      const r = await runCheck(stg, m.check, m.env, off);
      const skip = r.code === 0 && /^NOT RUN:/m.test(r.out);
      const rx = m.expect ? new RegExp(m.expect, 'm') : null;
      const hit = rx ? (r.out.split('\n').find((l) => rx.test(l)) || '') : (failLines(r.out)[0] || '');
      const base = clean.get(m.check);
      let verdict;
      if (skip) verdict = 'NOT RUN';
      else if (r.timedOut) verdict = 'TIMED OUT';
      else if (r.code !== 0 && (!rx || hit)) verdict = base && base.code !== 0 ? 'UNPROVEN' : 'caught';
      else verdict = 'SURVIVED';
      return { verdict, r, hit: hit.trim().slice(0, 200) };
    });
    results.push(Object.assign({ m }, res));
    const tag = res.verdict === 'caught' ? 'caught  ' : res.verdict.padEnd(8);
    console.log(`  ${tag} ${m.check.padEnd(18)} ${m.id.padEnd(26)} ${res.r ? (res.r.ms / 1000).toFixed(1) + 's' : ''}`
      + (res.hit ? '\n           ' + res.hit : '') + (res.note ? '\n           ' + res.note : ''));
    if (res.verdict !== 'caught' && res.r) {
      const fl = failLines(res.r.out);
      console.log('           exit ' + res.r.code + (fl.length ? '; its FAIL lines: ' + fl.slice(0, 4).join(' | ') : '; no FAIL line') + '\n           last: ' + res.r.out.trim().split('\n').slice(-2).join(' / ').slice(0, 240));
    }
  });

  const count = (v) => results.filter((x) => x.verdict === v).length;
  const bad = results.filter((x) => x.verdict !== 'caught');
  const covered = new Set(results.filter((x) => x.verdict === 'caught').map((x) => x.m.check));
  const none = allChecks().filter((c) => !MUTANTS.some((m) => m.check === c));
  console.log(`\n  ${count('caught')}/${results.length} mutants caught, for the reason named, over ${covered.size} check(s)`
    + (bad.length ? `  -  NOT: ${bad.map((x) => x.m.check + '/' + x.m.id + ' (' + x.verdict + ')').join(', ')}` : ''));
  console.log(`  NOT COVERED BY THIS RUN: every assertion a mutant here does not aim at; ${none.length} check(s) with no mutant at all`
    + (none.length ? ' (' + none.join(', ') + ')' : '') + (filters.length ? '; and every mutant the filter left out' : '') + '\n');
  process.exit(bad.length ? 1 : 0);
})();
